const COUNTER_KEY="tempotech_review_count";function incrementCounter(){const current=parseInt(localStorage.getItem(COUNTER_KEY)||"0",10);const updated=current+1;localStorage.setItem(COUNTER_KEY,updated);return updated;}
function getFormData(){const params=new URLSearchParams(window.location.search);const data={};params.forEach((value,key)=>{if(data[key]){data[key]=[].concat(data[key],value);}else{data[key]=value;}});return data;}
function formatKey(key){const map={productName:"Product ID",rating:"Rating",installDate:"Install Date",features:"Useful Features",writtenReview:"Written Review",userName:"Reviewer Name"};return map[key]||key;}
function starsDisplay(n){const num=parseInt(n,10);return"★".repeat(num)+"☆".repeat(5-num)+`  (${num}/5)`;}
function formatFeatures(val){if(!val)return"None selected";const arr=Array.isArray(val)?val:[val];return arr.map(f=>f.replace(/-/g," ").replace(/\b\w/g,c=>c.toUpperCase())).join(", ");}
function buildSummary(data){const container=document.getElementById("reviewSummary");if(!container)return;const orderedKeys=["productName","rating","installDate","features","writtenReview","userName"];orderedKeys.forEach(key=>{if(!(key in data))return;let val=data[key];if(!val||val==="")return;if(key==="rating")val=starsDisplay(val);if(key==="features")val=formatFeatures(val);const row=document.createElement("div");row.className="review-row";row.innerHTML=`<span class="r-key">${formatKey(key)}</span><span class="r-val">${val}</span>`;container.appendChild(row);});if(container.children.length===0){container.innerHTML=`<p style="color:var(--text-dim); font-size:0.85rem;">No submission data found.</p>`;}}
document.addEventListener("DOMContentLoaded",()=>{const count=incrementCounter();const counterEl=document.getElementById("reviewCounter");if(counterEl)counterEl.textContent=count;const data=getFormData();buildSummary(data);});